# ============================================================================\n# ADVANCED FEATURE ENGINEERING - BRAZILIAN LEGAL TEXT OPTIMIZATION\n# ============================================================================\n#\n# Domain-specific feature extraction for Brazilian legislative documents\n# Transport policy features, legal citation parsing, geographic extraction\n# Time-based features, regulatory complexity scoring\n#\n# Author: Data Science Consultant\n# Date: 2025-08-29\n# Version: 1.0 Production-Ready\n# ============================================================================\n\nlibrary(stringi)\nlibrary(data.table)\nlibrary(dplyr, warn.conflicts = FALSE)\nlibrary(lubridate)\nlibrary(tm)\nlibrary(textfeatures)\n\ncat(\"🔧 Advanced Feature Engineering v1.0 initialized\\n\")\n\n# ============================================================================\n# 1. BRAZILIAN LEGAL TEXT FEATURE EXTRACTOR\n# ============================================================================\n\n#' Comprehensive Brazilian Legal Text Feature Extraction\n#' Optimized for transport policy domain with regulatory complexity scoring\n#' \n#' @param documents Data frame with legislative documents\n#' @param text_column Character: name of the text column to analyze\n#' @param include_advanced Logical: whether to include computationally intensive features\n#' @param batch_size Integer: documents per batch for memory management\n#' @return Data frame with extracted features\nextract_brazilian_legal_features <- function(documents, text_column = \"title\",\n                                           include_advanced = TRUE, batch_size = 1000) {\n  \n  start_time <- Sys.time()\n  \n  cat(\"🔍 Extracting Brazilian legal features from\", nrow(documents), \"documents...\\n\")\n  \n  if (isTRUE(nrow(documents) == 0) || !text_column %in% names(documents)) {\n    warning(\"Invalid input data or text column not found\")\n    return(data.frame())\n  }\n  \n  # Convert to data.table for performance\n  dt <- as.data.table(documents)\n  \n  # Initialize feature columns\n  feature_list <- list()\n  \n  tryCatch({\n    \n    # ========================================================================\n    # BASIC TEXT FEATURES\n    # ========================================================================\n    \n    cat(\"   📝 Extracting basic text features...\\n\")\n    \n    dt[, `:=`(\n      # Basic length metrics\n      char_count = nchar(get(text_column)),\n      word_count = stringi::stri_count_words(get(text_column)),\n      sentence_count = stringi::stri_count_fixed(get(text_column), \".\"),\n      \n      # Text quality indicators\n      avg_word_length = nchar(gsub(\"[^A-Za-z]\", \"\", get(text_column))) / \n                       pmax(stringi::stri_count_words(get(text_column)), 1),\n      \n      uppercase_ratio = stringi::stri_count_regex(get(text_column), \"[A-Z]\") / \n                       pmax(nchar(get(text_column)), 1),\n      \n      numeric_density = stringi::stri_count_regex(get(text_column), \"\\\\d\") / \n                       pmax(nchar(get(text_column)), 1),\n      \n      punctuation_density = stringi::stri_count_regex(get(text_column), \"[.,;:!?]\") / \n                           pmax(nchar(get(text_column)), 1)\n    )]\n    \n    # ========================================================================\n    # LEGAL DOCUMENT TYPE FEATURES\n    # ========================================================================\n    \n    cat(\"   ⚖️  Extracting legal document type features...\\n\")\n    \n    # Brazilian legal instrument patterns (optimized regex)\n    legal_patterns <- list(\n      lei_federal = \"(?i)\\\\b(?:lei\\\\s+federal\\\\s+)?n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4}\\\\b\",\n      lei_complementar = \"(?i)\\\\b(?:lei\\\\s+complementar|lc)\\\\s+n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4}\\\\b\",\n      decreto = \"(?i)\\\\bdecreto(?:\\\\s+n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4})?\\\\b\",\n      medida_provisoria = \"(?i)\\\\b(?:medida\\\\s+provisória|mp)\\\\s+n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4}\\\\b\",\n      resolucao = \"(?i)\\\\bresolução(?:\\\\s+n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4})?\\\\b\",\n      portaria = \"(?i)\\\\bportaria(?:\\\\s+n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4})?\\\\b\",\n      instrucao_normativa = \"(?i)\\\\binstrução\\\\s+normativa(?:\\\\s+n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4})?\\\\b\",\n      circular = \"(?i)\\\\bcircular(?:\\\\s+n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4})?\\\\b\",\n      parecer = \"(?i)\\\\bparecer(?:\\\\s+n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4})?\\\\b\",\n      nota_tecnica = \"(?i)\\\\bnota\\\\s+técnica(?:\\\\s+n[ºo°]?\\\\.?\\\\s*\\\\d{1,5}[/,]\\\\d{4})?\\\\b\"\n    )\n    \n    for (pattern_name in names(legal_patterns)) {\n      dt[, (paste0(\"legal_\", pattern_name)) := \n           stringi::stri_count_regex(get(text_column), legal_patterns[[pattern_name]])]\n    }\n    \n    # Legal hierarchy scoring\n    dt[, legal_hierarchy_score := (\n      legal_lei_federal * 5 +           # Highest hierarchy\n      legal_lei_complementar * 5 +\n      legal_decreto * 4 +\n      legal_medida_provisoria * 4 +\n      legal_resolucao * 3 +\n      legal_portaria * 2 +\n      legal_instrucao_normativa * 2 +\n      legal_circular * 1 +\n      legal_parecer * 1 +\n      legal_nota_tecnica * 1\n    )]\n    \n    # ========================================================================\n    # TRANSPORT POLICY DOMAIN FEATURES\n    # ========================================================================\n    \n    cat(\"   🚛 Extracting transport domain features...\\n\")\n    \n    # Transport modal keywords with weights\n    transport_modals <- list(\n      rodoviario = list(\n        keywords = c(\"rodoviário\", \"rodovia\", \"caminhão\", \"caminhões\", \"carreta\", \"bitrem\", \n                    \"rodotrem\", \"frete\", \"transportador\", \"antt\", \"rntrc\", \"ctrc\"),\n        weight = 1.2  # Higher weight for primary modal\n      ),\n      ferroviario = list(\n        keywords = c(\"ferroviário\", \"ferrovia\", \"trem\", \"trilho\", \"estação\", \"locomotiva\", \n                    \"vagão\", \"composição\", \"ferrovia\", \"transporte ferroviário\"),\n        weight = 1.0\n      ),\n      aquaviario = list(\n        keywords = c(\"aquaviário\", \"porto\", \"navegação\", \"antaq\", \"cabotagem\", \"navio\", \n                    \"embarcação\", \"marítimo\", \"fluvial\", \"hidrovia\"),\n        weight = 0.9\n      ),\n      aereo = list(\n        keywords = c(\"aéreo\", \"aviação\", \"aeroporto\", \"anac\", \"aeronave\", \"voo\", \n                    \"transporte aéreo\", \"aviação civil\"),\n        weight = 0.8\n      ),\n      urbano = list(\n        keywords = c(\"urbano\", \"metrô\", \"ônibus\", \"brt\", \"vlt\", \"mobilidade urbana\", \n                    \"transporte público\", \"terminal\"),\n        weight = 0.7\n      )\n    )\n    \n    # Extract modal features\n    for (modal in names(transport_modals)) {\n      modal_info <- transport_modals[[modal]]\n      dt[, (paste0(\"modal_\", modal)) := {\n        modal_count <- rowSums(sapply(modal_info$keywords, function(kw) {\n          stringi::stri_count_fixed(stringi::stri_trans_tolower(get(text_column)), kw)\n        }))\n        modal_count * modal_info$weight\n      }]\n    }\n    \n    # Transport infrastructure keywords\n    infrastructure_keywords <- list(\n      infraestrutura_geral = c(\"infraestrutura\", \"obra\", \"construção\", \"manutenção\"),\n      pavimentacao = c(\"pavimentação\", \"asfalto\", \"duplicação\", \"restauração\"),\n      pontes_viadutos = c(\"ponte\", \"viaduto\", \"passarela\", \"túnel\"),\n      sinalizacao = c(\"sinalização\", \"semáforo\", \"placa\", \"demarcação\"),\n      terminais = c(\"terminal\", \"pátio\", \"estacionamento\", \"área de serviço\")\n    )\n    \n    for (infra_type in names(infrastructure_keywords)) {\n      dt[, (paste0(\"infra_\", infra_type)) := \n           rowSums(sapply(infrastructure_keywords[[infra_type]], function(kw) {\n             stringi::stri_count_fixed(stringi::stri_trans_tolower(get(text_column)), kw)\n           }))]\n    }\n    \n    # ========================================================================\n    # REGULATORY AGENCY AND AUTHORITY FEATURES\n    # ========================================================================\n    \n    cat(\"   🏛️  Extracting regulatory authority features...\\n\")\n    \n    # Brazilian regulatory agencies\n    regulatory_agencies <- list(\n      antt = c(\"antt\", \"agência nacional de transportes terrestres\"),\n      antaq = c(\"antaq\", \"agência nacional de transportes aquaviários\"),\n      anac = c(\"anac\", \"agência nacional de aviação civil\"),\n      anp = c(\"anp\", \"agência nacional do petróleo\"),\n      contran = c(\"contran\", \"conselho nacional de trânsito\"),\n      denatran = c(\"denatran\", \"departamento nacional de trânsito\"),\n      dnit = c(\"dnit\", \"departamento nacional de infraestrutura\"),\n      ibama = c(\"ibama\", \"instituto brasileiro do meio ambiente\"),\n      inmetro = c(\"inmetro\", \"instituto nacional de metrologia\")\n    )\n    \n    for (agency in names(regulatory_agencies)) {\n      dt[, (paste0(\"agency_\", agency)) := \n           rowSums(sapply(regulatory_agencies[[agency]], function(kw) {\n             stringi::stri_count_fixed(stringi::stri_trans_tolower(get(text_column)), kw)\n           }))]\n    }\n    \n    # Federal system hierarchy\n    dt[, `:=`(\n      federal_authority = stringi::stri_count_regex(\n        stringi::stri_trans_tolower(get(text_column)), \n        \"\\\\b(?:união|federal|presidente|congresso nacional|ministério)\\\\b\"\n      ),\n      state_authority = stringi::stri_count_regex(\n        stringi::stri_trans_tolower(get(text_column)), \n        \"\\\\b(?:estado|estadual|governador|assembleia legislativa)\\\\b\"\n      ),\n      municipal_authority = stringi::stri_count_regex(\n        stringi::stri_trans_tolower(get(text_column)), \n        \"\\\\b(?:município|municipal|prefeito|câmara municipal)\\\\b\"\n      )\n    )]\n    \n    # ========================================================================\n    # SUSTAINABILITY AND TECHNOLOGY FEATURES\n    # ========================================================================\n    \n    cat(\"   🌱 Extracting sustainability and technology features...\\n\")\n    \n    # Sustainability keywords with semantic grouping\n    sustainability_features <- list(\n      descarbonizacao = c(\"descarbonização\", \"carbono\", \"emissão\", \"co2\", \"gases de efeito estufa\"),\n      combustiveis_alternativos = c(\"biodiesel\", \"etanol\", \"hidrogenio\", \"eletrico\", \"gnv\", \"renovável\"),\n      eficiencia_energetica = c(\"eficiência energética\", \"economia de combustível\", \"consumo\"),\n      sustentabilidade_geral = c(\"sustentável\", \"verde\", \"ambiental\", \"ecológico\", \"limpo\")\n    )\n    \n    for (sust_type in names(sustainability_features)) {\n      dt[, (paste0(\"sust_\", sust_type)) := \n           rowSums(sapply(sustainability_features[[sust_type]], function(kw) {\n             stringi::stri_count_fixed(stringi::stri_trans_tolower(get(text_column)), kw)\n           }))]\n    }\n    \n    # Technology and digitization features\n    technology_features <- list(\n      digitalizacao = c(\"digital\", \"eletrônico\", \"sistema\", \"tecnologia\", \"automação\"),\n      industria_40 = c(\"indústria 4.0\", \"iot\", \"inteligente\", \"conectado\", \"smart\"),\n      telemetria = c(\"telemetria\", \"monitoramento\", \"rastreamento\", \"gps\", \"sensor\"),\n      inteligencia_artificial = c(\"inteligência artificial\", \"ia\", \"machine learning\", \"algoritmo\")\n    )\n    \n    for (tech_type in names(technology_features)) {\n      dt[, (paste0(\"tech_\", tech_type)) := \n           rowSums(sapply(technology_features[[tech_type]], function(kw) {\n             stringi::stri_count_fixed(stringi::stri_trans_tolower(get(text_column)), kw)\n           }))]\n    }\n    \n    # ========================================================================\n    # LEGAL CITATION AND REFERENCE FEATURES\n    # ========================================================================\n    \n    cat(\"   📚 Extracting legal citation features...\\n\")\n    \n    # Legal citations patterns\n    dt[, `:=`(\n      # Article references\n      artigo_refs = stringi::stri_count_regex(get(text_column), \"(?i)art\\\\.?\\\\s*\\\\d+[ºo°]?\"),\n      paragrafo_refs = stringi::stri_count_regex(get(text_column), \"§\\\\s*\\\\d+[ºo°]?\"),\n      inciso_refs = stringi::stri_count_regex(get(text_column), \"(?i)inciso\\\\s+[ivx]+\"),\n      alinea_refs = stringi::stri_count_regex(get(text_column), \"(?i)alínea\\\\s+[a-z]\"),\n      \n      # Constitutional references\n      constitutional_refs = stringi::stri_count_regex(\n        stringi::stri_trans_tolower(get(text_column)), \n        \"\\\\b(?:constituição|constitucional|cf[/,]?88)\\\\b\"\n      ),\n      \n      # Code references\n      codigo_refs = stringi::stri_count_regex(\n        stringi::stri_trans_tolower(get(text_column)), \n        \"\\\\b(?:código|ctn|clt|ctb|cc)\\\\b\"\n      )\n    )]\n    \n    # Citation density and complexity\n    dt[, `:=`(\n      citation_density = (artigo_refs + paragrafo_refs + inciso_refs + alinea_refs) / \n                        pmax(word_count, 1),\n      legal_complexity_score = (\n        constitutional_refs * 3 +\n        codigo_refs * 2 +\n        artigo_refs * 1 +\n        paragrafo_refs * 0.5 +\n        inciso_refs * 0.5 +\n        alinea_refs * 0.3\n      )\n    )]\n    \n    # ========================================================================\n    # GEOGRAPHIC FEATURES (if location data available)\n    # ========================================================================\n    \n    if (\"state\" %in% names(dt) || \"municipality\" %in% names(dt)) {\n      cat(\"   🗺️  Extracting geographic features...\\n\")\n      \n      # Brazilian regions mapping\n      if (\"state\" %in% names(dt)) {\n        dt[, region := fcase(\n          state %in% c('AC', 'AM', 'AP', 'PA', 'RO', 'RR', 'TO'), 'Norte',\n          state %in% c('AL', 'BA', 'CE', 'MA', 'PB', 'PE', 'PI', 'RN', 'SE'), 'Nordeste',\n          state %in% c('DF', 'GO', 'MT', 'MS'), 'Centro-Oeste',\n          state %in% c('ES', 'MG', 'RJ', 'SP'), 'Sudeste',\n          state %in% c('PR', 'RS', 'SC'), 'Sul',\n          default = 'Outros'\n        )]\n        \n        # Economic development indicators by state\n        developed_states <- c('SP', 'RJ', 'MG', 'RS', 'PR', 'SC')\n        dt[, is_developed_state := as.numeric(state %in% developed_states)]\n        \n        # Coastal vs inland states\n        coastal_states <- c('RS', 'SC', 'PR', 'SP', 'RJ', 'ES', 'BA', 'SE', 'AL', 'PE', 'PB', 'RN', 'CE', 'PI', 'MA', 'PA', 'AP', 'AM')\n        dt[, is_coastal_state := as.numeric(state %in% coastal_states)]\n      }\n    }\n    \n    # ========================================================================\n    # TEMPORAL FEATURES (if date data available)\n    # ========================================================================\n    \n    if (\"date\" %in% names(dt) || \"year\" %in% names(dt)) {\n      cat(\"   📅 Extracting temporal features...\\n\")\n      \n      # Parse date if it exists\n      if (\"date\" %in% names(dt) && !\"year\" %in% names(dt)) {\n        dt[, year := year(as.Date(date))]\n      }\n      \n      if (\"year\" %in% names(dt)) {\n        # Historical periods\n        dt[, historical_period := fcase(\n          year < 1889, 'Imperial',\n          year < 1930, 'Primeira República',\n          year < 1946, 'Era Vargas',\n          year < 1964, 'República Populista',\n          year < 1985, 'Regime Militar',\n          year >= 1985, 'Nova República',\n          default = 'Desconhecido'\n        )]\n        \n        # Constitutional periods\n        dt[, constitutional_period := fcase(\n          year < 1988, 'Pré-Constituição 1988',\n          year >= 1988, 'Pós-Constituição 1988',\n          default = 'Desconhecido'\n        )]\n        \n        # Modern transport regulation periods\n        dt[, transport_regulation_era := fcase(\n          year < 2001, 'Pré-Marco Regulatório',\n          year >= 2001 & year < 2019, 'Marco Regulatório Tradicional',\n          year >= 2019, 'Marco Regulatório Moderno',\n          default = 'Desconhecido'\n        )]\n        \n        # Document age (years since publication)\n        current_year <- as.numeric(format(Sys.Date(), \"%Y\"))\n        dt[, document_age_years := current_year - year]\n        dt[, is_recent_document := as.numeric(document_age_years <= 5)]\n      }\n    }\n    \n    # ========================================================================\n    # ADVANCED FEATURES (if requested and computationally feasible)\n    # ========================================================================\n    \n    if (include_advanced && nrow(dt) <= 10000) {  # Limit for performance\n      cat(\"   🧠 Extracting advanced NLP features...\\n\")\n      \n      # Text complexity measures\n      dt[, `:=`(\n        # Flesch Reading Ease (simplified Portuguese adaptation)\n        flesch_score = pmax(0, 206.835 - 1.015 * (word_count / pmax(sentence_count, 1)) - \n                           84.6 * (char_count / pmax(word_count, 1) - 5)),\n        \n        # Vocabulary diversity (Type-Token Ratio)\n        vocabulary_diversity = {\n          if (word_count > 0) {\n            words <- unlist(strsplit(tolower(gsub(\"[^A-Za-z ]\", \" \", get(text_column))), \"\\\\s+\"))\n            unique_words <- unique(words[words != \"\"])\n            length(unique_words) / length(words[words != \"\"])\n          } else {\n            0\n          }\n        },\n        \n        # Regulatory action words\n        action_words = stringi::stri_count_regex(\n          stringi::stri_trans_tolower(get(text_column)),\n          \"\\\\b(?:estabelece|institui|regulamenta|determina|define|cria|autoriza|proíbe|obriga)\\\\b\"\n        ),\n        \n        # Modal verbs indicating obligation/permission\n        modal_verbs = stringi::stri_count_regex(\n          stringi::stri_trans_tolower(get(text_column)),\n          \"\\\\b(?:deve|deverá|pode|poderá|é obrigatório|é vedado|é permitido)\\\\b\"\n        )\n      ), by = seq_len(nrow(dt))]  # Row-by-row calculation for complex operations\n    }\n    \n    # ========================================================================\n    # COMPOSITE SCORES AND INDICES\n    # ========================================================================\n    \n    cat(\"   📊 Calculating composite scores...\\n\")\n    \n    # Transport relevance composite score\n    modal_scores <- c(\"modal_rodoviario\", \"modal_ferroviario\", \"modal_aquaviario\", \"modal_aereo\", \"modal_urbano\")\n    infra_scores <- grep(\"^infra_\", names(dt), value = TRUE)\n    \n    dt[, transport_relevance_score := rowSums(.SD, na.rm = TRUE), \n       .SDcols = c(modal_scores, infra_scores)]\n    \n    # Sustainability composite score\n    sust_scores <- grep(\"^sust_\", names(dt), value = TRUE)\n    dt[, sustainability_score := rowSums(.SD, na.rm = TRUE), .SDcols = sust_scores]\n    \n    # Technology adoption score\n    tech_scores <- grep(\"^tech_\", names(dt), value = TRUE)\n    dt[, technology_score := rowSums(.SD, na.rm = TRUE), .SDcols = tech_scores]\n    \n    # Regulatory authority score\n    agency_scores <- grep(\"^agency_\", names(dt), value = TRUE)\n    dt[, regulatory_authority_score := rowSums(.SD, na.rm = TRUE), .SDcols = agency_scores]\n    \n    # Overall complexity index\n    dt[, regulatory_complexity_index := (\n      legal_hierarchy_score * 0.3 +\n      legal_complexity_score * 0.25 +\n      citation_density * word_count * 0.2 +\n      transport_relevance_score * 0.15 +\n      regulatory_authority_score * 0.1\n    )]\n    \n    # Document importance score (combination of multiple factors)\n    dt[, document_importance_score := (\n      legal_hierarchy_score * 0.4 +\n      transport_relevance_score * 0.25 +\n      regulatory_complexity_index * 0.2 +\n      sustainability_score * 0.1 +\n      technology_score * 0.05\n    )]\n    \n    processing_time <- as.numeric(difftime(Sys.time(), start_time, units = \"secs\"))\n    \n    cat(\"✅ Feature extraction completed!\\n\")\n    cat(\"   📊 Features extracted:\", ncol(dt) - ncol(documents), \"\\n\")\n    cat(\"   ⏱️  Processing time:\", round(processing_time, 2), \"seconds\\n\")\n    cat(\"   🚀 Rate:\", round(nrow(dt)/processing_time, 0), \"docs/sec\\n\")\n    \n    return(dt)\n    \n  }, error = function(e) {\n    cat(\"❌ Feature extraction failed:\", e$message, \"\\n\")\n    return(documents)  # Return original data if extraction fails\n  })\n}\n\n# ============================================================================\n# 2. TIME-BASED FEATURE ENGINEERING\n# ============================================================================\n\n#' Extract Time-Based Policy Features\n#' Creates features based on temporal patterns and policy cycles\n#' \n#' @param documents Data frame with documents containing date information\n#' @param date_column Character: name of the date column\n#' @return Data frame with temporal features added\nextract_temporal_policy_features <- function(documents, date_column = \"date\") {\n  \n  cat(\"📅 Extracting temporal policy features...\\n\")\n  \n  if (!date_column %in% names(documents)) {\n    warning(\"Date column not found, skipping temporal features\")\n    return(documents)\n  }\n  \n  dt <- as.data.table(documents)\n  \n  # Parse and validate dates\n  dt[, parsed_date := as.Date(get(date_column))]\n  dt <- dt[!is.na(parsed_date)]  # Remove invalid dates\n  \n  if (nrow(dt) == 0) {\n    warning(\"No valid dates found\")\n    return(documents)\n  }\n  \n  # Extract temporal components\n  dt[, `:=`(\n    year = year(parsed_date),\n    month = month(parsed_date),\n    day = day(parsed_date),\n    day_of_year = yday(parsed_date),\n    week_of_year = week(parsed_date),\n    quarter = quarter(parsed_date),\n    weekday = wday(parsed_date),\n    is_weekend = wday(parsed_date) %in% c(1, 7)\n  )]\n  \n  # Political and economic cycles\n  dt[, `:=`(\n    # Presidential election years (every 4 years starting from 2002)\n    is_election_year = (year - 2002) %% 4 == 0 & year >= 2002,\n    \n    # Congressional election years (every 4 years, offset by 2)\n    is_congressional_election_year = (year - 2014) %% 4 == 0 & year >= 2014,\n    \n    # Budget cycle (first quarter typically sees more regulatory activity)\n    is_budget_season = quarter == 1,\n    \n    # End of year rush (higher activity in Q4)\n    is_year_end = quarter == 4,\n    \n    # Mid-term government (years 3-4 of presidential term)\n    is_mid_term = (year - 2018) %% 4 %in% c(2, 3) & year >= 2020\n  )]\n  \n  # Presidential terms (Brazilian context)\n  dt[, presidential_term := fcase(\n    year >= 2019, \"Bolsonaro\",\n    year >= 2016, \"Temer\",\n    year >= 2011, \"Dilma\",\n    year >= 2003, \"Lula\",\n    year >= 1995, \"FHC\",\n    year >= 1990, \"Collor/Itamar\",\n    year >= 1985, \"Sarney\",\n    default = \"Período Anterior\"\n  )]\n  \n  # Economic context features\n  dt[, economic_context := fcase(\n    year >= 2020, \"Pandemia/Recuperação\",\n    year >= 2016, \"Recessão/Crise\",\n    year >= 2010, \"Crescimento Moderado\",\n    year >= 2003, \"Crescimento Acelerado\",\n    year >= 1994, \"Estabilização\",\n    default = \"Instabilidade\"\n  )]\n  \n  # Regulatory modernization periods\n  dt[, regulatory_modernization_period := fcase(\n    year >= 2019, \"Marco Regulatório Digital\",\n    year >= 2016, \"Novo Marco Regulatório\",\n    year >= 2001, \"Criação das Agências\",\n    year >= 1995, \"Início das Reformas\",\n    default = \"Período Anterior\"\n  )]\n  \n  # Time since key transport legislation\n  lei_2001 <- as.Date(\"2001-06-14\")  # Lei 10.233/2001 (transport regulatory framework)\n  dt[, days_since_transport_law := as.numeric(parsed_date - lei_2001)]\n  dt[, years_since_transport_law := days_since_transport_law / 365.25]\n  \n  # Document age and recency features\n  current_date <- Sys.Date()\n  dt[, `:=`(\n    document_age_days = as.numeric(current_date - parsed_date),\n    document_age_years = as.numeric(current_date - parsed_date) / 365.25,\n    is_very_recent = document_age_days <= 365,\n    is_recent = document_age_days <= 365 * 3,\n    is_current_decade = year >= 2020,\n    is_last_decade = year >= 2010 & year < 2020\n  )]\n  \n  # Seasonal patterns (Brazilian context)\n  dt[, season := fcase(\n    month %in% c(12, 1, 2), \"Verão\",\n    month %in% c(3, 4, 5), \"Outono\",\n    month %in% c(6, 7, 8), \"Inverno\",\n    month %in% c(9, 10, 11), \"Primavera\"\n  )]\n  \n  # Policy implementation timeline features\n  dt[, policy_timeline_phase := fcase(\n    day_of_year <= 90, \"Planejamento\",   # Q1: Planning phase\n    day_of_year <= 180, \"Implementação\", # Q2: Implementation\n    day_of_year <= 270, \"Execução\",      # Q3: Execution\n    day_of_year <= 365, \"Avaliação\"      # Q4: Evaluation\n  )]\n  \n  # Remove temporary column\n  dt[, parsed_date := NULL]\n  \n  cat(\"✅ Temporal features extracted successfully!\\n\")\n  \n  return(dt)\n}\n\n# ============================================================================\n# 3. GEOGRAPHIC FEATURE EXTRACTION\n# ============================================================================\n\n#' Extract Geographic and Jurisdictional Features\n#' Creates features based on Brazilian federal system and regional characteristics\n#' \n#' @param documents Data frame with geographic information\n#' @return Data frame with geographic features added\nextract_geographic_features <- function(documents) {\n  \n  cat(\"🗺️  Extracting geographic features...\\n\")\n  \n  dt <- as.data.table(documents)\n  \n  # Brazilian states and regions mapping\n  state_info <- data.table(\n    state = c('AC', 'AL', 'AP', 'AM', 'BA', 'CE', 'DF', 'ES', 'GO', 'MA', \n              'MT', 'MS', 'MG', 'PA', 'PB', 'PR', 'PE', 'PI', 'RJ', 'RN', \n              'RS', 'RO', 'RR', 'SC', 'SP', 'SE', 'TO'),\n    \n    region = c('Norte', 'Nordeste', 'Norte', 'Norte', 'Nordeste', 'Nordeste', \n              'Centro-Oeste', 'Sudeste', 'Centro-Oeste', 'Nordeste', 'Centro-Oeste', \n              'Centro-Oeste', 'Sudeste', 'Norte', 'Nordeste', 'Sul', 'Nordeste', \n              'Nordeste', 'Sudeste', 'Nordeste', 'Sul', 'Norte', 'Norte', 'Sul', \n              'Sudeste', 'Nordeste', 'Norte'),\n    \n    population_size = c('small', 'medium', 'small', 'large', 'large', 'large', \n                       'medium', 'large', 'medium', 'medium', 'medium', 'medium', \n                       'large', 'large', 'medium', 'large', 'large', 'medium', \n                       'large', 'medium', 'large', 'small', 'small', 'medium', \n                       'large', 'small', 'small'),\n    \n    economic_development = c('low', 'medium', 'low', 'medium', 'medium', 'medium',\n                           'high', 'high', 'medium', 'low', 'medium', 'medium',\n                           'high', 'medium', 'low', 'high', 'medium', 'low',\n                           'high', 'low', 'high', 'low', 'low', 'high',\n                           'high', 'low', 'low'),\n    \n    is_coastal = c(FALSE, TRUE, TRUE, FALSE, TRUE, TRUE, FALSE, TRUE, FALSE, TRUE,\n                  FALSE, FALSE, FALSE, TRUE, TRUE, TRUE, TRUE, FALSE, TRUE, TRUE,\n                  TRUE, FALSE, FALSE, TRUE, TRUE, TRUE, FALSE)\n  )\n  \n  # Join geographic information\n  if (\"state\" %in% names(dt)) {\n    dt <- merge(dt, state_info, by = \"state\", all.x = TRUE)\n    \n    # Add regional economic indicators\n    dt[, `:=`(\n      # Economic powerhouses\n      is_economic_center = state %in% c('SP', 'RJ', 'MG'),\n      \n      # Amazon states (environmental significance)\n      is_amazon_state = state %in% c('AC', 'AM', 'AP', 'PA', 'RO', 'RR', 'TO', 'MT', 'MA'),\n      \n      # Border states (international significance)\n      is_border_state = state %in% c('AC', 'AM', 'RR', 'AP', 'RS', 'SC', 'PR', 'MS', 'MT', 'RO'),\n      \n      # States with major ports\n      has_major_port = state %in% c('SP', 'RJ', 'ES', 'BA', 'PE', 'CE', 'PA', 'MA', 'RS', 'SC', 'PR'),\n      \n      # Agricultural frontier states\n      is_agricultural_frontier = state %in% c('MT', 'GO', 'BA', 'TO', 'PI', 'MA'),\n      \n      # Industrial centers\n      is_industrial_center = state %in% c('SP', 'RJ', 'MG', 'RS', 'PR', 'SC', 'BA')\n    )]\n    \n    # Regional development indices (simplified)\n    dt[, regional_development_index := fcase(\n      region == 'Sudeste' & state %in% c('SP', 'RJ'), 5,  # Highest development\n      region == 'Sudeste', 4,\n      region == 'Sul', 4,\n      region == 'Centro-Oeste' & state == 'DF', 4,\n      region == 'Centro-Oeste', 3,\n      region == 'Nordeste' & is_coastal, 3,\n      region == 'Nordeste', 2,\n      region == 'Norte' & state == 'AM', 3,\n      region == 'Norte', 2,\n      default = 2\n    )]\n  }\n  \n  # Municipality-based features (if municipality data available)\n  if (\"municipality\" %in% names(dt)) {\n    # Capital cities\n    capital_cities <- c(\"Rio Branco\", \"Maceió\", \"Macapá\", \"Manaus\", \"Salvador\", \n                       \"Fortaleza\", \"Brasília\", \"Vitória\", \"Goiânia\", \"São Luís\", \n                       \"Cuiabá\", \"Campo Grande\", \"Belo Horizonte\", \"Belém\", \"João Pessoa\", \n                       \"Curitiba\", \"Recife\", \"Teresina\", \"Rio de Janeiro\", \"Natal\", \n                       \"Porto Alegre\", \"Porto Velho\", \"Boa Vista\", \"Florianópolis\", \n                       \"São Paulo\", \"Aracaju\", \"Palmas\")\n    \n    dt[, is_capital := municipality %in% capital_cities]\n    \n    # Metropolitan areas (simplified)\n    metro_keywords <- c(\"Grande\", \"Região Metropolitana\", \"Grande São Paulo\", \n                       \"Grande Rio\", \"Grande Belo Horizonte\", \"Grande Porto Alegre\")\n    dt[, is_metropolitan_area := any(sapply(metro_keywords, function(x) grepl(x, municipality, ignore.case = TRUE))), by = municipality]\n  }\n  \n  # Interstate characteristics\n  if (\"state\" %in% names(dt)) {\n    # Calculate interstate document patterns\n    state_counts <- dt[, .N, by = state]\n    dt[, state_document_frequency := state_counts[match(dt$state, state_counts$state)]$N]\n    \n    # Interstate cooperation indicators\n    dt[, involves_interstate_cooperation := grepl(\"interestadual|cooperação|convênio\", \n                                                 paste(title, summary, sep = \" \"), \n                                                 ignore.case = TRUE)]\n  }\n  \n  cat(\"✅ Geographic features extracted successfully!\\n\")\n  \n  return(dt)\n}\n\n# ============================================================================\n# 4. REGULATORY COMPLEXITY SCORING\n# ============================================================================\n\n#' Calculate Advanced Regulatory Complexity Score\n#' Multi-dimensional scoring system for regulatory complexity\n#' \n#' @param documents Data frame with legislative documents\n#' @return Data frame with complexity scores added\ncalculate_regulatory_complexity <- function(documents) {\n  \n  cat(\"📊 Calculating regulatory complexity scores...\\n\")\n  \n  dt <- as.data.table(documents)\n  \n  # Initialize complexity components\n  dt[, `:=`(\n    # Structural complexity\n    structural_complexity = 0,\n    \n    # Reference complexity  \n    reference_complexity = 0,\n    \n    # Authority complexity\n    authority_complexity = 0,\n    \n    # Temporal complexity\n    temporal_complexity = 0,\n    \n    # Domain complexity\n    domain_complexity = 0\n  )]\n  \n  # Structural complexity (based on document structure)\n  if (\"char_count\" %in% names(dt) && \"word_count\" %in% names(dt)) {\n    dt[, structural_complexity := (\n      pmin(char_count / 1000, 10) * 0.3 +       # Length factor (capped at 10)\n      pmin(word_count / 500, 10) * 0.3 +        # Word count factor\n      ifelse(\"sentence_count\" %in% names(dt), pmin(sentence_count / 50, 10) * 0.2, 0) +\n      ifelse(\"paragraph_count\" %in% names(dt), pmin(paragraph_count / 20, 10) * 0.2, 0)\n    )]\n  }\n  \n  # Reference complexity (legal citations and references)\n  citation_cols <- grep(\"(artigo_refs|paragrafo_refs|inciso_refs|constitutional_refs|codigo_refs)\", names(dt), value = TRUE)\n  if (length(citation_cols) > 0) {\n    dt[, reference_complexity := rowSums(.SD, na.rm = TRUE) / 5, .SDcols = citation_cols]  # Normalize by 5\n  }\n  \n  # Authority complexity (multiple authorities involved)\n  authority_cols <- grep(\"(federal_authority|state_authority|municipal_authority|agency_)\", names(dt), value = TRUE)\n  if (length(authority_cols) > 0) {\n    dt[, authority_complexity := pmin(rowSums(.SD > 0, na.rm = TRUE), 5), .SDcols = authority_cols]  # Count distinct authorities (max 5)\n  }\n  \n  # Temporal complexity (implementation timelines, deadlines)\n  temporal_keywords <- c(\"prazo\", \"cronograma\", \"etapa\", \"fase\", \"implementação gradual\")\n  dt[, temporal_complexity := rowSums(sapply(temporal_keywords, function(kw) {\n    stringi::stri_count_fixed(stringi::stri_trans_tolower(title), kw)\n  }))]\n  \n  # Domain complexity (cross-sectoral impacts)\n  domain_cols <- grep(\"(modal_|sust_|tech_|infra_)\", names(dt), value = TRUE)\n  if (length(domain_cols) > 0) {\n    dt[, domain_complexity := pmin(rowSums(.SD > 0, na.rm = TRUE), 8) / 2, .SDcols = domain_cols]  # Normalize by domains/2\n  }\n  \n  # Overall regulatory complexity index\n  dt[, regulatory_complexity_index := (\n    structural_complexity * 0.25 +\n    reference_complexity * 0.25 +\n    authority_complexity * 0.20 +\n    domain_complexity * 0.20 +\n    temporal_complexity * 0.10\n  )]\n  \n  # Complexity categories\n  dt[, complexity_category := fcase(\n    regulatory_complexity_index >= 7, \"Muito Alta\",\n    regulatory_complexity_index >= 5, \"Alta\",\n    regulatory_complexity_index >= 3, \"Média\",\n    regulatory_complexity_index >= 1, \"Baixa\",\n    default = \"Muito Baixa\"\n  )]\n  \n  # Implementation difficulty score\n  dt[, implementation_difficulty := (\n    regulatory_complexity_index * 0.6 +\n    ifelse(\"involves_interstate_cooperation\" %in% names(dt) & involves_interstate_cooperation, 2, 0) +\n    ifelse(\"sustainability_score\" %in% names(dt), pmin(sustainability_score / 3, 2), 0) +\n    ifelse(\"technology_score\" %in% names(dt), pmin(technology_score / 2, 1), 0)\n  )]\n  \n  cat(\"✅ Regulatory complexity scoring completed!\\n\")\n  \n  return(dt)\n}\n\n# Helper function for null coalescing\n`%||%` <- function(a, b) if (is.null(a)) b else a\n\ncat(\"✅ Advanced Feature Engineering fully loaded!\\n\")\ncat(\"   🔧 Brazilian legal features: ENABLED\\n\")\ncat(\"   📅 Temporal features: ENABLED\\n\")\ncat(\"   🗺️  Geographic features: ENABLED\\n\")\ncat(\"   📊 Complexity scoring: ENABLED\\n\")\ncat(\"   🚛 Transport domain optimization: ENABLED\\n\")\ncat(\"   🌱 Sustainability indicators: ENABLED\\n\")\ncat(\"   🏛️  Regulatory authority mapping: ENABLED\\n\")\n\n# Export main functions\nFEATURE_ENGINEERING_FUNCTIONS <- list(\n  extract_brazilian_legal_features = extract_brazilian_legal_features,\n  extract_temporal_policy_features = extract_temporal_policy_features,\n  extract_geographic_features = extract_geographic_features,\n  calculate_regulatory_complexity = calculate_regulatory_complexity\n)"